-- 4. Magazines
DROP TABLE IF EXISTS `magazines`;
CREATE TABLE `magazines` (
  `id` INT DEFAULT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `title` VARCHAR(255) DEFAULT NULL,
  `subtitle` VARCHAR(500) DEFAULT NULL,
  `desc` TEXT DEFAULT NULL,
  `theme_primary` VARCHAR(50) DEFAULT '#a31835',
  `theme_secondary` VARCHAR(50) DEFAULT '#3d0c1b',
  `gradient` VARCHAR(500) DEFAULT NULL,
  `hero_image` VARCHAR(500) DEFAULT NULL,
  `essence_image` VARCHAR(500) DEFAULT NULL,
  `hero_buttons` LONGTEXT DEFAULT NULL,
  `essence_title` VARCHAR(255) DEFAULT NULL,
  `tabs` LONGTEXT DEFAULT NULL,
  `sections` LONGTEXT DEFAULT NULL,
  `rubriques` LONGTEXT DEFAULT NULL,
  `config_data` LONGTEXT DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `magazines` (`id`, `slug`, `title`, `subtitle`, `desc`, `theme_primary`, `theme_secondary`, `gradient`, `hero_image`, `essence_image`, `hero_buttons`, `essence_title`, `tabs`, `sections`, `rubriques`, `config_data`, `created_at`, `updated_at`) VALUES (1, 'magazine-01-intelligence', 'Intelligence', 'Savoir & Décision', 'Stratégies et analyses pour un esprit affûté.', '#a31835', '#3d0c1b', 'linear-gradient(135deg, #2b1126, #411d3d)', '/assets/core/img/mag_hero_01.png', '/assets/core/img/mag_hero_02.png', '[{"id":"btn-1","label":"Explorer les Éditions","url":"#articles","visible":true},{"id":"btn-2","label":"S\'abonner au Magazine","url":"/abonnement","visible":true}]', 'L\'Essence de Intelligence', '[{"id":"tab-1","slug":"analyses","name":"Analyses","order":1,"defaultActive":true,"hidden":false},{"id":"tab-2","slug":"dossiers","name":"Dossiers","order":2,"defaultActive":false,"hidden":false},{"id":"tab-3","slug":"actualites","name":"Actualités","order":3,"defaultActive":false,"hidden":false}]', '[{"id":"sec-hero","type":"HERO","name":"Hero Banner","visible":true,"order":1},{"id":"sec-essence","type":"PRESENTATION","name":"Présentation Éditoriale","visible":true,"order":2},{"id":"sec-tabs","type":"CATEGORIES_FEED","name":"Onglets & Articles","visible":true,"order":3},{"id":"sec-tools","type":"TOOLS","name":"Outils & Services","visible":true,"order":4},{"id":"sec-cta","type":"CTA_PREMIUM","name":"Appel à l\'Abonnement","visible":true,"order":5}]', '[]', '{"id":1,"slug":"magazine-01-intelligence","title":"Intelligence","subtitle":"Savoir & Décision","desc":"Stratégies et analyses pour un esprit affûté.","themePrimary":"#a31835","themeSecondary":"#3d0c1b","gradient":"linear-gradient(135deg, #2b1126, #411d3d)","heroImage":"/assets/core/img/mag_hero_01.png","essenceImage":"/assets/core/img/mag_hero_02.png","heroButtons":[{"id":"btn-1","label":"Explorer les Éditions","url":"#articles","visible":true},{"id":"btn-2","label":"S\'abonner au Magazine","url":"/abonnement","visible":true}],"essenceTitle":"L\'Essence de Intelligence","essenceText":"Sous la direction de la Pr Nora Patrius, ce magazine explore les frontières de la connaissance stratégique. Nous décryptons les signaux faibles pour transformer l\'information brute en une intelligence actionnable pour les décideurs de demain.","essenceQuote":"L\'intelligence n\'est pas seulement l\'accumulation de données, c\'est l\'art de discerner le motif au milieu du chaos.","tabs":[{"id":"tab-1","slug":"analyses","name":"Analyses","order":1,"defaultActive":true,"hidden":false},{"id":"tab-2","slug":"dossiers","name":"Dossiers","order":2,"defaultActive":false,"hidden":false},{"id":"tab-3","slug":"actualites","name":"Actualités","order":3,"defaultActive":false,"hidden":false}],"sections":[{"id":"sec-hero","type":"HERO","name":"Hero Banner","visible":true,"order":1},{"id":"sec-essence","type":"PRESENTATION","name":"Présentation Éditoriale","visible":true,"order":2},{"id":"sec-tabs","type":"CATEGORIES_FEED","name":"Onglets & Articles","visible":true,"order":3},{"id":"sec-tools","type":"TOOLS","name":"Outils & Services","visible":true,"order":4},{"id":"sec-cta","type":"CTA_PREMIUM","name":"Appel à l\'Abonnement","visible":true,"order":5}],"rubriques":[],"features":[{"title":"The Brief","subtitle":"SYNTHÈSE QUOTIDIENNE STRATÉGIQUE","meta":"EST. 2024 • 08:00 CET","icon":"assignment"},{"title":"The Pulse","subtitle":"SIGNAUX FAIBLES & DÉTECTION PRÉCOCE","meta":"LIVE UPDATE • GLOBAL FEED","icon":"sensors"},{"title":"Deep-Dive","subtitle":"ANALYSES DE FOND PAR NOS EXPERTS","meta":"MONTHLY REV. • 40 PAGE PDF","icon":"search"},{"title":"Radar","subtitle":"CARTOGRAPHIE DES RISQUES ÉMERGENTS","meta":"DYNAMIC MAP • Q4 FOCUS","icon":"shield"}]}', '2026-08-31 10:17:22', '2026-09-03 11:54:09');
