visible":true}],"essenceTitle":"L\'Essence de Power Lab","essenceText":"Sous la direction du Dr Marc Valette, Power Lab explore les technologies de rupture et les méthodologies de performance extrême pour propulser vos projets vers l\'avenir.","essenceQuote":"La performance n\'est pas un accident. C\'est le résultat d\'une attention obsessionnelle aux détails et à l\'innovation.","tabs":[{"id":"tab-1","slug":"analyses","name":"Analyses","order":1,"defaultActive":true,"hidden":false},{"id":"tab-2","slug":"dossiers","name":"Dossiers","order":2,"defaultActive":false,"hidden":false},{"id":"tab-3","slug":"actualites","name":"Actualités","order":3,"defaultActive":false,"hidden":false}],"sections":[{"id":"sec-hero","type":"HERO","name":"Hero Banner","visible":true,"order":1},{"id":"sec-essence","type":"PRESENTATION","name":"Présentation Éditoriale","visible":true,"order":2},{"id":"sec-tabs","type":"CATEGORIES_FEED","name":"Onglets & Articles","visible":true,"order":3},{"id":"sec-tools","type":"TOOLS","name":"Outils & Services","visible":true,"order":4},{"id":"sec-cta","type":"CTA_PREMIUM","name":"Appel à l\'Abonnement","visible":true,"order":5}],"rubriques":[],"features":[{"title":"The Pulse","subtitle":"VECTEURS D\'INNOVATION RAPIDE","meta":"REAL-TIME • EXPERIMENTAL","icon":"bolt"},{"title":"Lab Reports","subtitle":"RAPPORTS DE RECHERCHE R&D","meta":"WEEKLY • DETAILED ANALYTICS","icon":"biotech"},{"title":"Beta Test","subtitle":"ACCÈS ANTICIPÉ AUX OUTILS","meta":"EXCLUSIVE MEMBERS ONLY","icon":"science"},{"title":"Metrics","subtitle":"KPI & RENDEMENT","meta":"MONTHLY DASHBOARD","icon":"speed"}]}', '2026-08-31 10:17:22', '2026-09-03 11:54:09');
INSERT INTO `magazines` (`id`, `slug`, `title`, `subtitle`, `desc`, `theme_primary`, `theme_secondary`, `gradient`, `hero_image`, `essence_image`, `hero_buttons`, `essence_title`, `tabs`, `sections`, `rubriques`, `config_data`, `created_at`, `updated_at`) VALUES (3, 'magazine-03-alliance', 'L\'Alliance', 'Réseaux & Influence', 'Le pouvoir des réseaux et des connexions.', '#a30626', '#6c1626', 'linear-gradient(135deg, #6c1626, #9c2741)', '/assets/core/img/mag_hero_03.png', '/assets/core/img/mag_hero_04.png', '[{"id":"btn-1","label":"Explorer les Éditions","url":"#articles","visible":true},{"id":"btn-2","label":"S\'abonner au Magazine","url":"/abonnement","visible":true}]', 'L\'Essence de L\'Alliance', '[{"id":"tab-1","slug":"analyses","name":"Analyses","order":1,"defaultActive":true,"hidden":false},{"id":"tab-2","slug":"dossiers","name":"Dossiers","order":2,"defaultActive":false,"hidden":false},{"id":"tab-3","slug":"actualites","name":"Actualités","order":3,"defaultActive":false,"hidden":false}]', '[{"id":"sec-hero","type":"HERO","name":"Hero Banner","visible":true,"order":1},{"id":"sec-essence","type":"PRESENTATION","name":"Présentation Éditoriale","visible":true,"order":2},{"id":"sec-tabs","type":"CATEGORIES_FEED","name":"Onglets & Articles","visible":true,"order":3},{"id":"sec-tools","type":"TOOLS","name":"Outils & Services","visible":true,"order":4},{"id":"sec-cta","type":"CTA_PREMIUM","name":"Appel à l\'Abonnement","visible":true,"order":5}]', '[]', '{"id":3,"slug":"magazine-03-alliance","title":"L\'Alliance","subtitle":"Réseaux & Influence","desc":"Le pouvoir des réseaux et des connexions.","themePrimary":"#a30626","themeSecondary":"#6c1626","gradient":"linear-gradient(135deg, #6c1626, #9c2741)","heroImage":"/assets/core/img/mag_hero_03.png","essenceImage":"/assets/core/img/mag_hero_04.png","heroButtons":[{"id":"btn-1","label":"Explorer les Éditions","url":"#articles","visible":true},{"id":"btn-2","label":"S\'abonner au Magazine","url":"/abonnement","visible":true}],"essenceTitle":"L\'Essence de L\'Alliance","essenceText":"L\'Alliance décrypte les structures de réseau qui régissent le pouvoir contemporain. Apprenez à bâtir des connexions stratégiques durables et à étendre votre influence légitime.","essenceQuote":"La force d\'un individu ne réside pas dans son isolement, mais dans la richesse et la confiance des réseaux qu\'il tisse.","tabs":[{"id":"tab-1","slug":"analyses","name":"Analyses","order":1,"defaultActive":true,"hidden":false},{"id":"tab-2","slug":"dossiers","name":"Dossiers","order":2,"defaultActive":false,"hidden":false},{"id":"tab-3","slug":"actualites","name":"Actualités","order":3,"defaultActive":false,"hidden":false}],"sections":[{"id":"sec-hero","type":"HERO","name":"Hero Banner","visible":true,"order":1},{"id":"sec-essence","type":"PRESENTATION","name":"Présentation Éditoriale","visible":true,"order":2},{"id":"sec-tabs","type":"CATEGORIES_FEED","name":"Onglets & Articles","visible":true,"order":3},{"id":"sec-tools","type":"TOOLS","name":"Outils & Services","visible":true,"order":4},{"id":"sec-cta","type":"CTA_PREMIUM","name":"Appel à l\'Abonnement","visible":true,"order":5}],"rubriques":[],"features":[{"title":"Net Map","subtitle":"CARTOGRAPHIE DES CERCLES DE POUVOIR","meta":"UPDATED Q3","icon":"hub"},{"title":"Briefing","subtitle":"INTELLIGENCE RELATIONNELLE","meta":"FORTNIGHTLY","icon":"forum"}]}', '2026-09-03 11:54:09', '2026-09-03 11:54:09');
INSERT INTO `magazines` (`id`, `slug`, `title`, `subtitle`, `desc`, `theme_primary`, `theme_secondary`, `gradient`, `hero_image`, `essence_image`, `hero_buttons`, `essence_title`, `tabs`, `sections`, `rubriques`, `config_data`, `created_at`, `updated_at`) VALUES (4, 'magazine-04-agenda', 'L\'Agenda', 'Temps & Excellence', 'Maîtrisez votre temps, orchestrez votre succès.', '#b09159', '#8f703c', 'linear-gradient(135deg, #b09159, #cfb17d)', '/assets/core/img/mag_hero_04.png', '/assets/core/img/mag_hero_05.png', '[{"id":"btn-1","label":"Explorer les Éditions","url":"#articles","visible":true},{"id":"btn-2","label":"S\'abonner au Magazine","url":"/abonnement","visible":true}]', 'L\'Essence de L\'Agenda', '[{"id":"tab-1","slug":"analyses","name":"Analyses","order":1,"defaultActive":true,"hidden":false},{"id":"tab-2","slug":"dossiers","name":"Dossiers","order":2,"defaultActive":false,"hidden":false},{"id":"tab-3","slug":"actualites","name":"Actualités","order":3,"defaultActive":false,"hidden":false}]', '[{"id":"sec-hero","type":"HERO","name":"Hero Banner","visible":true,"order":1},{"id":"sec-essence","type":"PRESENTATION","name":"Présentation Éditoriale","visible":true,"order":2},{"id":"sec-tabs","type":"CATEGORIES_FEED","name":"Onglets & Articles","visible":true,"order":3},{"id":"sec-tools","type":"TOOLS","name":"Outils & Services","visible":true,"order":4},{"id":"sec-cta","type":"CTA_PREMIUM","name":"Appel à l\'Abonnement","visible":true,"order":5}]', '[]', '{"id":4,"slug":"magazine-04-agenda","title":"L\'Agenda","subtitle":"Temps & Excellence","desc":"Maîtrisez votre temps, orchestrez votre succès.","themePrimary":"#b09159","themeSecondary":"#8f703c","gradient":"linear-gradient(135deg, #b09159, #cfb17d)","heroImage":"/assets/core/img/mag_hero_04.png","essenceImage":"/assets/core/img/mag_hero_05.png","heroButtons":[{"id":"btn-1","label":"Explorer les Éditions","url":"#articles","visible":true},{"id":"btn-2","label":"S\'abonner au Magazine","url":"/abonnement","visible":true}],"essenceTitle":"L\'Essence de L\'Agenda","essenceText":"L\'Agenda propose une philosophie moderne du temps. Apprenez à concevoir vos journées comme des oeuvres d\'art pour maximiser votre impact et atteindre l\'équilibre absolu.","essenceQuote":"Celui qui ne maîtrise pas son temps est condamné à bâtir le rêve d\'un autre.","tabs":[{"id":"tab-1","slug":"analyses","name":"Analyses","order":1,"defaultActive":true,"hidden":false},{"id":"tab-2","slug":"dossiers","name":"Dossiers","order":2,"defaultActive":false,"hidden":false},{"id":"tab-3","slug":"actualites","name":"Actualités","order":3,"defaultActive":false,"hidden":false}],"sections":[{"id":"sec-hero","type":"HERO","name":"Hero Banner","visible":true,"order":1},{"id":"sec-essence","type":"PRESENTATION","name":"Présentation Éditoriale","visible":true,"order":2},{"id":"sec-tabs","type":"CATEGORIES_FEED","name":"Onglets & Articles","visible":true,"order":3},{"id":"sec-tools","type":"TOOLS","name":"Outils & Services","visible":true,"order":4},{"id":"sec-cta","type":"CTA_PREMIUM","name":"Appel à l\'Abonnement","visible":true,"order":5}],"rubriques":[],"features":[{"title":"FlowState","subtitle":"MÉTHODOLOGIE DE CONCENTRATION","meta":"PRACTICAL GUIDE","icon":"hourglass_empty"}]}', '2026-09-03 11:54:09', '2026-09-03 11:54:09');
