INSERT INTO `today_page_config` (`id`, `hero`, `filters`, `news_items`, `editorial`, `values_list`, `france`, `updated_at`) VALUES ('main', '{"id":"hero","status":"Published","title":"DONA : La\\nRenaissance\\nde la Femme Solaire","subtitle":"\\"Une femme affirmée, positive, ambitieuse et rayonnante,\\nen harmonie avec son époque.\\"","button1Label":"DÉCOUVRIR DONA","button1Url":"#","button2Label":"LIRE LE MANIFESTE","button2Url":"#","image":"/assets/core/img/hero_solaire.png","updated":"À l\'instant"}', '[{"id":"f1","label":"TOUTES","url":"#","updated":"—"},{"id":"f2","label":"GÉOPOLITIQUE","url":"#","updated":"—"},{"id":"f3","label":"ÉCONOMIE","url":"#","updated":"—"},{"id":"f4","label":"BUSINESS","url":"#","updated":"—"},{"id":"f5","label":"INNOVATION","url":"#","updated":"—"},{"id":"f6","label":"SOCIÉTÉ","url":"#","updated":"—"},{"id":"f7","label":"CULTURE","url":"#","updated":"—"}]', '[{"id":"news-1","status":"Published","isFeatured":true,"isNew":true,"time":"15:00","title":"Accord historique sur la parité salariale au sein de l\'Union Européenne","desc":"Après des mois de négociations intenses, le Parlement a adopté ce matin une directive contraignante, marquant un tournant décisif pour l\'égalité économique.","content":"<p>Après des mois de négociations intenses, le Parlement a adopté ce matin une directive contraignante, marquant un tournant décisif pour l\'égalité économique.</p>","image":"/assets/core/img/featured_urgent.png","updated":"À l\'instant"},{"id":"news-2","status":"Published","isFeatured":false,"isNew":true,"time":"14:30","title":"Nominations à la tête des grandes banques centrales","desc":"Trois femmes pressenties pour diriger les institutions clés en Asie et en Europe.","content":"","updated":"À l\'instant"},{"id":"news-3","status":"Published","isFeatured":false,"isNew":false,"time":"13:15","title":"COP29 : Les initiatives climatiques portées par des entrepreneures","desc":"Le sommet met en lumière des solutions innovantes développées par des startups.","content":"","updated":"À l\'instant"},{"id":"news-4","status":"Published","isFeatured":false,"isNew":false,"time":"11:45","title":"Rétrospective : L\'impact de l\'architecture inclusive","desc":"Comment la nouvelle vague de designers redessine les espaces publics.","content":"","updated":"À l\'instant"}]', '{"id":"editorial","status":"Published","sectionLabel":"NOTRE ÉDITORIAL","title":"Notre Vision\\nRéconciliée","content":"<p>Le magazine DONA porte une vision réconciliée de la femme moderne. Loin des clivages épuisants, nous célébrons une féminité qui embrasse la réussite professionnelle sans sacrifier la grâce, l\'élégance et l\'accomplissement personnel.</p>","points":[{"id":1,"title":"L\'Harmonie plutôt que le combat","desc":"Cultiver sa force intérieure dans la sérénité."},{"id":2,"title":"L\'Ambition assumée","desc":"Viser l\'excellence dans toutes les sphères de la vie."}],"quote":"\\"L\'élégance n\'est pas de se faire remarquer, mais de s\'en souvenir. C\'est cette trace lumineuse que laisse la femme DONA.\\"","image":"/assets/core/img/vision_portrait.png","updated":"—"}', '[{"id":"val-1","status":"Published","title":"Heureuse","desc":"Cultiver la joie quotidienne comme une discipline de vie et un moteur de créativité.","updated":"—"},{"id":"val-2","status":"Published","title":"Affirmée","desc":"Posséder une voix claire, poser des limites saines et assumer ses convictions.","updated":"—"},{"id":"val-3","status":"Published","title":"Ambitieuse","desc":"Vouloir plus grand, sans s\'excuser, et se donner les moyens d\'atteindre l\'excellence.","updated":"—"},{"id":"val-4","status":"Published","title":"Rayonnante","desc":"Être une source d\'inspiration lumineuse pour son entourage et sa communauté.","updated":"—"}]', '[{"id":"fr-1","status":"Published","category":"POLITIQUE","time":"Il y a 45 min","title":"Loi Égalité Professionnelle : Le Sénat adopte le texte en première lecture","desc":"Les quotas dans les comités de direction des grandes entreprises seront renforcés dès 2026.","content":"","image":"/assets/core/img/france_1.png","updated":"—"},{"id":"fr-2","status":"Published","category":"ÉCONOMIE","time":"Il y a 2h","title":"CAC 40 : Les entreprises dirigées par des femmes surperforment","desc":"Une nouvelle étude démontre une rentabilité supérieure de 12% pour les groupes à parité.","content":"","image":"/assets/core/img/france_2.png","updated":"—"},{"id":"fr-3","status":"Published","category":"CULTURE","time":"Il y a 4h","title":"Cannes 2026 : Record historique de femmes réalisatrices en sélection officielle","desc":"Thierry Frémaux annonce une sélection paritaire pour la première fois dans l\'histoire du festival.","content":"","image":"/assets/core/img/france_3.png","updated":"—"}]', '2026-08-31 13:21:46');

