-- 10. Orders & Transactions
DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders` (
  `id` VARCHAR(100) NOT NULL,
  `user_id` VARCHAR(100) DEFAULT NULL,
  `customer_name` VARCHAR(255) NOT NULL,
  `customer_email` VARCHAR(255) NOT NULL,
  `plan` VARCHAR(100) NOT NULL,
  `plan_name` VARCHAR(255) NOT NULL,
  `billing_cycle` VARCHAR(50) DEFAULT 'mensuel',
  `subtotal` DECIMAL(10,2) NOT NULL,
  `tax` DECIMAL(10,2) NOT NULL,
  `discount` DECIMAL(10,2) DEFAULT 0.00,
  `promo_code` VARCHAR(100) DEFAULT NULL,
  `total` DECIMAL(10,2) NOT NULL,
  `currency` VARCHAR(10) DEFAULT 'EUR',
  `payment_method` VARCHAR(100) DEFAULT 'Carte bancaire',
  `card_brand` VARCHAR(50) DEFAULT 'VISA',
  `card_last4` VARCHAR(10) DEFAULT '4242',
  `billing_address` TEXT DEFAULT NULL,
  `status` VARCHAR(50) DEFAULT 'Completed',
  `next_billing_date` DATETIME DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_orders_customer_email` (`customer_email`),
  KEY `idx_orders_status` (`status`),
  KEY `idx_orders_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

